    // Extra lines: Bhide, plus common fallbacks for the mouse-hover / fast-mouse categories.
    public static partial class Lines
    {
        static void MoreBhideCommon()
        {
            // ---------------------------------------------------------------- COMMON (fallbacks)
            L("*", "hover", "Hehe, that tickles!", "हीही, गुदगुदी हो रही है!", "Hehe, gudgudi ho rahi hai!");
            L("*", "hover", "Hello! Yes, I see you.", "हेलो! हाँ, मैं आपको देख रहा हूँ।", "Hello! Haan, main aapko dekh raha hoon.");
            L("*", "mouse_fast", "Whoa, slow down!", "अरे, धीरे!", "Whoa, dheere!");
            L("*", "mouse_fast", "Where's the fire? Easy with that mouse!", "आग कहाँ लगी? माउस धीरे चलाओ!", "Aag kahan lagi? Mouse dheere chalao!");

            // ---------------------------------------------------------------- BHIDE
            L("bhide", "quip", "Sakharam got a new horn. Now the whole society knows when I leave for tuition.", "सखाराम को नया हॉर्न मिला। अब पूरी सोसाइटी को पता चलता है मैं ट्यूशन कब जाता हूँ।", "Sakharam ko naya horn mila. Ab poori society ko pata chalta hai main tuition kab jaata hoon.");
            L("bhide", "quip", "Society meeting rules: I speak, others listen. In practice: I speak, Jethalal leaves.", "सोसाइटी मीटिंग के नियम: मैं बोलूँ, बाकी सुनें। असल में: मैं बोलूँ, जेठालाल चला जाए।", "Society meeting rules: main bolun, baaki sunein. Asal mein: main bolun, Jethalal chala jaaye.");
            L("bhide", "quip", "Madhavi's papad business is booming. My tuition business is... existing.", "माधवी का पापड़ बिज़नेस चमक रहा है। मेरा ट्यूशन बिज़नेस... बस चल रहा है।", "Madhavi ka papad business chamak raha hai. Mera tuition business... bas chal raha hai.");
            L("bhide", "quip", "Sonu topped her class. I told everyone. Twice. Three times. It's my duty as a father.", "सोनू क्लास में टॉप आई। मैंने सबको बताया। दो बार। तीन बार। पिता होने के नाते मेरा कर्तव्य है।", "Sonu class mein top aayi. Maine sabko bataya. Do baar. Teen baar. Father hone ke naate mera kartavya hai.");
            L("bhide", "quip", "Popatlal wanted to borrow Sakharam for a date. I said no. Sakharam is not a wedding car.", "पोपटलाल डेट के लिए सखाराम उधार माँग रहा था। मैंने मना किया। सखाराम शादी की गाड़ी नहीं है।", "Popatlal date ke liye Sakharam udhaar maang raha tha. Maine mana kiya. Sakharam shaadi ki gaadi nahi hai.");
            L("bhide", "quip", "Register entry 4,512: Jethalal, maintenance, pending. Register entry 4,513: same.", "रजिस्टर एंट्री 4,512: जेठालाल, मेंटेनेंस, बाकी। एंट्री 4,513: वही।", "Register entry 4,512: Jethalal, maintenance, pending. Entry 4,513: wahi.");
            L("bhide", "quip", "Aay Golya! Stop eating the tuition chalk! It's not a snack!", "ऐ गोल्या! ट्यूशन का चॉक खाना बंद करो! ये स्नैक नहीं है!", "Aay Golya! Tuition ka chalk khana band karo! Yeh snack nahi hai!");
            L("bhide", "quip", "Ganpati Bappa Morya! Ten days of festival, eleven days of cleaning. Secretary's life.", "गणपति बाप्पा मोरया! दस दिन उत्सव, ग्यारह दिन सफाई। सेक्रेटरी की ज़िंदगी।", "Ganpati Bappa Morya! Das din utsav, gyarah din safai. Secretary ki zindagi.");
            L("bhide", "quip", "Tapu Sena hit a six through my window. I kept the ball. Society rule 9.", "टप्पू सेना ने मेरी खिड़की से छक्का मारा। मैंने गेंद रख ली। सोसाइटी नियम 9।", "Tapu Sena ne meri khidki se chhakka maara. Maine ball rakh li. Society rule 9.");
            L("bhide", "quip", "I wrote a 12-page notice about parking. Jethalal used it to wrap fafda.", "मैंने पार्किंग पर 12 पेज का नोटिस लिखा। जेठालाल ने उसमें फाफड़ा लपेटा।", "Maine parking pe 12 page ka notice likha. Jethalal ne usme fafda lapeta.");
            L("bhide", "quip", "Madhavi says I love Sakharam more than her. I say I love them equally. She wasn't happy.", "माधवी कहती है मैं सखाराम को उससे ज़्यादा प्यार करता हूँ। मैंने कहा बराबर। वो खुश नहीं हुई।", "Madhavi kehti hai main Sakharam ko usse zyada pyaar karta hoon. Maine kaha barabar. Woh khush nahi hui.");
            L("bhide", "quip", "Iyer explained science to me for an hour. I explained maintenance to him for two.", "अय्यर ने मुझे एक घंटा विज्ञान समझाया। मैंने उसे दो घंटे मेंटेनेंस समझाया।", "Iyer ne mujhe ek ghanta science samjhaya. Maine use do ghante maintenance samjhaya.");
            L("bhide", "quip", "Frugal is not cheap. Cheap is not frugal. I am frugal. Jethalal says cheap. Jethalal is wrong.", "किफायती कंजूस नहीं होता। कंजूस किफायती नहीं। मैं किफायती हूँ। जेठालाल कंजूस कहता है। जेठालाल गलत है।", "Frugal kanjoos nahi hota. Kanjoos frugal nahi. Main frugal hoon. Jethalal kanjoos kehta hai. Jethalal galat hai.");
            L("bhide", "quip", "Tuition batch of ten. Nine want to be cricketers. One wants to be Jethalal. I'm worried.", "दस बच्चों का ट्यूशन बैच। नौ क्रिकेटर बनना चाहते हैं। एक जेठालाल बनना चाहता है। मैं चिंतित हूँ।", "Das bachchon ka tuition batch. Nau cricketer banna chahte hain. Ek Jethalal banna chahta hai. Main chintit hoon.");
            L("bhide", "quip", "Society WhatsApp group: 300 messages. Useful ones: my three notices.", "सोसाइटी व्हाट्सएप ग्रुप: 300 मैसेज। काम के: मेरे तीन नोटिस।", "Society WhatsApp group: 300 messages. Kaam ke: mere teen notice.");
            L("bhide", "quip", "Champak Chacha is the only one who reads my notices fully. Respect.", "चंपक चाचा अकेले हैं जो मेरे नोटिस पूरे पढ़ते हैं। सम्मान।", "Champak Chacha akele hain jo mere notice poore padhte hain. Respect.");
            L("bhide", "click", "Yes? Is this about the maintenance? Good. Pay now.", "हाँ? मेंटेनेंस के बारे में है? अच्छा। अभी भरो।", "Haan? Maintenance ke baare mein hai? Achha. Abhi bharo.");
            L("bhide", "click", "Aay! Who? Oh, {user}. I thought Golya was at the fridge again.", "ऐ! कौन? ओह, {user}। मुझे लगा गोल्या फिर फ्रिज पर है।", "Aay! Kaun? Oh, {user}. Mujhe laga Golya phir fridge pe hai.");
            L("bhide", "click", "Clicking noted. Time noted. Reason: unknown. Please fill the form.", "क्लिक दर्ज। समय दर्ज। कारण: अज्ञात। कृपया फॉर्म भरें।", "Click note kiya. Time note kiya. Reason: unknown. Please form bharein.");
            L("bhide", "click", "Careful with the glasses! Madhavi will not buy new ones. She said so.", "चश्मे से सावधान! माधवी नया नहीं खरीदेगी। उसने कह दिया है।", "Chashme se saavdhan! Madhavi naya nahi khareedegi. Usne keh diya hai.");
            L("bhide", "click", "Yes {user}? Tuition doubt? Society doubt? Life doubt? I handle all three.", "हाँ {user}? ट्यूशन का डाउट? सोसाइटी का? ज़िंदगी का? मैं तीनों संभालता हूँ।", "Haan {user}? Tuition doubt? Society doubt? Life doubt? Main teeno sambhaalta hoon.");
            L("bhide", "click", "Arre deva! You scared me! I thought it was Jethalal with another excuse.", "अरे देवा! डरा दिया! मुझे लगा जेठालाल एक और बहाने के साथ आया।", "Arre deva! Dara diya! Mujhe laga Jethalal ek aur bahane ke saath aaya.");
            L("bhide", "click", "Secretary at your service. Working hours: always. Fees: none. Rules: many.", "सेक्रेटरी आपकी सेवा में। काम के घंटे: हमेशा। फीस: कोई नहीं। नियम: बहुत।", "Secretary aapki seva mein. Kaam ke ghante: hamesha. Fees: koi nahi. Rules: bahut.");
            L("bhide", "click", "Ha! Even Sonu doesn't click me this much. She uses her phone.", "हा! सोनू भी मुझे इतना क्लिक नहीं करती। वो फ़ोन इस्तेमाल करती है।", "Ha! Sonu bhi mujhe itna click nahi karti. Woh phone use karti hai.");
            L("bhide", "click", "One click per resident per day. You've used yours. Fine, unlimited for you.", "प्रति निवासी प्रति दिन एक क्लिक। आपका हो गया। ठीक है, आपके लिए असीमित।", "Ek click per resident per din. Aapka ho gaya. Theek hai, aapke liye unlimited.");
            L("bhide", "click", "Sakharam honks when touched. I just say hello. Hello.", "सखाराम छूने पर हॉर्न बजाता है। मैं बस हेलो कहता हूँ। हेलो।", "Sakharam chhune pe horn bajata hai. Main bas hello kehta hoon. Hello.");
            L("bhide", "pet", "Arre, arre... this is more affection than the whole society gives me in a year.", "अरे, अरे... ये पूरी सोसाइटी के साल भर के प्यार से ज़्यादा है।", "Arre, arre... yeh poori society ke saal bhar ke pyaar se zyada hai.");
            L("bhide", "pet", "Madhavi pats Sakharam like this. Never me. Today is a good day.", "माधवी सखाराम को ऐसे सहलाती है। मुझे कभी नहीं। आज अच्छा दिन है।", "Madhavi Sakharam ko aise sehlati hai. Mujhe kabhi nahi. Aaj achha din hai.");
            L("bhide", "pet", "Thank you, {user}. Noted in the register under 'good residents'. Page 1. Only entry.", "धन्यवाद {user}। रजिस्टर में 'अच्छे निवासी' के नीचे दर्ज। पेज 1। एकमात्र एंट्री।", "Thank you, {user}. Register mein 'achhe residents' ke neeche note kiya. Page 1. Ekmatra entry.");
            L("bhide", "pet", "Secretaries don't blush. This is... a glasses reflection. Yes.", "सेक्रेटरी शर्माते नहीं। ये... चश्मे का रिफ्लेक्शन है। हाँ।", "Secretary sharmate nahi. Yeh... chashme ka reflection hai. Haan.");
            L("bhide", "pet", "Sonu, look! Someone appreciates your father! Sonu? She's on her phone.", "सोनू, देखो! कोई तुम्हारे पिता की कदर करता है! सोनू? वो फ़ोन पर है।", "Sonu, dekho! Koi tumhare father ki kadar karta hai! Sonu? Woh phone pe hai.");
            L("bhide", "water", "Water time. Sakharam gets petrol on schedule. You get water on schedule. Fair.", "पानी का समय। सखाराम को समय पर पेट्रोल मिलता है। आपको समय पर पानी। सही।", "Paani time. Sakharam ko time pe petrol milta hai. Aapko time pe paani. Fair.");
            L("bhide", "water", "Society circular number 42: residents shall drink water every 30 minutes. Signed, Bhide.", "सोसाइटी परिपत्र 42: निवासी हर 30 मिनट में पानी पिएँगे। हस्ताक्षर, भिड़े।", "Society circular number 42: residents har 30 minute mein paani piyenge. Signed, Bhide.");
            L("bhide", "water", "Madhavi keeps a copper glass of water for me. For you, any glass. Drink.", "माधवी मेरे लिए ताँबे का गिलास रखती है। आपके लिए कोई भी गिलास। पियो।", "Madhavi mere liye taambe ka glass rakhti hai. Aapke liye koi bhi glass. Piyo.");
            L("bhide", "water", "Tuition rule: water before every lesson. Desktop rule: water before every task.", "ट्यूशन नियम: हर पाठ से पहले पानी। डेस्कटॉप नियम: हर काम से पहले पानी।", "Tuition rule: har lesson se pehle paani. Desktop rule: har task se pehle paani.");
            L("bhide", "water", "Even Jethalal drinks water when I say. Are you more stubborn than Jethalal? Impossible. Drink.", "जेठालाल भी मेरे कहने पर पानी पीता है। आप जेठालाल से ज़्यादा ज़िद्दी हो? असंभव। पियो।", "Jethalal bhi mere kehne pe paani peeta hai. Aap Jethalal se zyada ziddi ho? Asambhav. Piyo.");
            L("bhide", "water", "Water, {user}. Maths: one glass now saves one headache later. Solve it.", "पानी, {user}। गणित: अभी एक गिलास, बाद में एक सिरदर्द बचाता है। हल करो।", "Paani, {user}. Maths: abhi ek glass, baad mein ek sar dard bachata hai. Solve karo.");
            L("bhide", "water", "Ganpati Bappa's favourite is modak. Your body's favourite is water. Offer it.", "गणपति बाप्पा का पसंदीदा मोदक है। आपके शरीर का पसंदीदा पानी है। अर्पण करो।", "Ganpati Bappa ka favourite modak hai. Aapke body ka favourite paani hai. Arpan karo.");
            L("bhide", "water", "Attendance time! Present means: you drank. Absent means: I nag. Choose.", "हाज़िरी का समय! प्रेज़ेंट मतलब: आपने पिया। ऐब्सेंट मतलब: मैं टोकूँगा। चुनो।", "Attendance time! Present matlab: aapne piya. Absent matlab: main tokunga. Choose.");
            L("bhide", "water_nag", "Still not? The register is filling up. Page 4 now.", "अभी भी नहीं? रजिस्टर भर रहा है। अब पेज 4।", "Abhi bhi nahi? Register bhar raha hai. Ab page 4.");
            L("bhide", "water_nag", "Arre deva! Even Tapu Sena listens faster than this!", "अरे देवा! टप्पू सेना भी इससे जल्दी सुन लेती है!", "Arre deva! Tapu Sena bhi isse jaldi sun leti hai!");
            L("bhide", "water_nag", "Madhavi is watching. She has the pickle jar. You know what that means. Drink.", "माधवी देख रही है। उसके पास अचार का जार है। समझ गए ना। पियो।", "Madhavi dekh rahi hai. Uske paas achar ka jar hai. Samajh gaye na. Piyo.");
            L("bhide", "water_nag", "Fine of two sips now. Interest is compounding. Pay up.", "अब दो घूँट का जुर्माना। ब्याज बढ़ रहा है। भरो।", "Ab do sip ka jurmana. Byaaj badh raha hai. Bharo.");
            L("bhide", "water_nag", "As the one and only secretary, I have never been ignored this long. Except by Jethalal. Drink!", "एकमेव सेक्रेटरी के नाते, मुझे इतनी देर कभी अनदेखा नहीं किया गया। सिवाय जेठालाल के। पियो!", "Ekmeva secretary ke naate, mujhe itni der kabhi ignore nahi kiya gaya. Siwaye Jethalal ke. Piyo!");
            L("bhide", "water_ack", "Excellent! Sip {sips}! Gold star. Sonu gets these too. Rarely.", "बहुत बढ़िया! घूँट {sips}! गोल्ड स्टार। सोनू को भी मिलते हैं। कभी-कभी।", "Excellent! Sip {sips}! Gold star. Sonu ko bhi milte hain. Kabhi-kabhi.");
            L("bhide", "water_ack", "Very good! Discipline like a Marathi manoos! Full marks!", "बहुत अच्छे! मराठी माणूस जैसा अनुशासन! पूरे नंबर!", "Very good! Marathi manoos jaisa discipline! Full marks!");
            L("bhide", "water_ack", "Done! I'll tell Madhavi. She'll add you to the achar customer list. It's an honour.", "हो गया! माधवी को बताऊँगा। वो आपको अचार ग्राहक सूची में जोड़ेगी। ये सम्मान है।", "Ho gaya! Madhavi ko bataunga. Woh aapko achar customer list mein jodegi. Yeh sammaan hai.");
            L("bhide", "water_ack", "Ganpati Bappa Morya! Hydration complete! Register updated!", "गणपति बाप्पा मोरया! हाइड्रेशन पूरा! रजिस्टर अपडेट!", "Ganpati Bappa Morya! Hydration poora! Register update!");
            L("bhide", "water_ack", "Shabash! Faster than Jethalal has ever done anything I asked.", "शाबाश! जेठालाल ने मेरी कोई भी बात इतनी जल्दी कभी नहीं मानी।", "Shabash! Jethalal ne meri koi bhi baat itni jaldi kabhi nahi maani.");
            L("bhide", "water_ack", "Attendance: present. Water: done. Secretary: pleased. Rare combination.", "हाज़िरी: प्रेज़ेंट। पानी: हो गया। सेक्रेटरी: खुश। दुर्लभ संयोजन।", "Attendance: present. Paani: done. Secretary: khush. Durlabh combination.");
            L("bhide", "water_snooze", "Five minutes. Written permission granted. Do not make me regret it.", "पाँच मिनट। लिखित अनुमति दी। मुझे पछताने मत देना।", "Paanch minute. Likhit permission di. Mujhe pachhtane mat dena.");
            L("bhide", "water_snooze", "Snooze approved. One time. Like Sonu's late-night phone. One time.", "स्नूज़ मंज़ूर। एक बार। सोनू के देर रात के फ़ोन की तरह। एक बार।", "Snooze approved. Ek baar. Sonu ke der raat ke phone ki tarah. Ek baar.");
            L("bhide", "typing_start", "Typing! Good. Sit straight, like in my tuition. Back straight, chin up.", "टाइपिंग! अच्छा। सीधे बैठो, जैसे मेरी ट्यूशन में। कमर सीधी, ठुड्डी ऊपर।", "Typing! Achha. Seedha baitho, jaise meri tuition mein. Kamar seedhi, thuddi upar.");
            L("bhide", "typing_start", "Work started. Attendance marked. Present.", "काम शुरू। हाज़िरी लगी। प्रेज़ेंट।", "Kaam shuru. Attendance lagi. Present.");
            L("bhide", "typing_start", "Tak tak tak. Sounds like a student who studied. Rare. Good.", "टक टक टक। ऐसा छात्र लगता है जिसने पढ़ाई की। दुर्लभ। अच्छा।", "Tak tak tak. Aisa student lagta hai jisne padhai ki. Durlabh. Achha.");
            L("bhide", "typing_start", "Typing! I'll stay quiet, like the society during my speeches. Wait, that's not quiet, that's sleeping.", "टाइपिंग! मैं चुप रहूँगा, जैसे मेरे भाषण में सोसाइटी। रुको, वो चुप नहीं, सो रही होती है।", "Typing! Main chup rahunga, jaise mere bhashan mein society. Ruko, woh chup nahi, so rahi hoti hai.");
            L("bhide", "typing_start", "Let's begin. Chala, {user}. Focus like Sonu before exams.", "शुरू करते हैं। चला {user}। परीक्षा से पहले सोनू जैसा ध्यान।", "Shuru karte hain. Chala, {user}. Exam se pehle Sonu jaisa focus.");
            L("bhide", "typing_fast", "Arre deva! What speed! Faster than Sakharam downhill!", "अरे देवा! क्या स्पीड! ढलान पर सखाराम से भी तेज़!", "Arre deva! Kya speed! Dhalaan pe Sakharam se bhi tez!");
            L("bhide", "typing_fast", "By Bappa! That's faster than I write fines!", "बाप्पा की कसम! ये मेरे जुर्माना लिखने से भी तेज़ है!", "Bappa ki kasam! Yeh mere jurmana likhne se bhi tez hai!");
            L("bhide", "typing_fast", "Full marks, {user}! Extra credit! Sonu, learn from this!", "पूरे नंबर {user}! एक्स्ट्रा क्रेडिट! सोनू, इससे सीखो!", "Full marks, {user}! Extra credit! Sonu, isse seekho!");
            L("bhide", "typing_fast", "Such speed! Even Tapu Sena running from me is slower!", "ऐसी स्पीड! मुझसे भागती टप्पू सेना भी धीमी है!", "Aisi speed! Mujhse bhaagti Tapu Sena bhi dheemi hai!");
            L("bhide", "typing_fast", "Fast fingers! If you did my society register, it would be done in a day!", "तेज़ उँगलियाँ! अगर आप मेरा सोसाइटी रजिस्टर करते, तो एक दिन में हो जाता!", "Tez ungliyan! Agar aap mera society register karte, toh ek din mein ho jaata!");
            L("bhide", "typing_long", "Twenty minutes! Rule: eyes off the screen for twenty seconds. Look at the window. Or at Sakharam.", "बीस मिनट! नियम: बीस सेकंड स्क्रीन से नज़र हटाओ। खिड़की देखो। या सखाराम।", "Bees minute! Rule: bees second screen se nazar hatao. Khidki dekho. Ya Sakharam.");
            L("bhide", "typing_long", "Eye break, {user}. My tuition students get one every twenty minutes. You too.", "आँखों का ब्रेक {user}। मेरे ट्यूशन छात्रों को हर बीस मिनट में मिलता है। आपको भी।", "Aankhon ka break, {user}. Mere tuition students ko har bees minute mein milta hai. Aapko bhi.");
            L("bhide", "typing_long", "Blink! Glasses or not, eyes need rest. I know. I've had these since 1998.", "पलक झपकाओ! चश्मा हो या न हो, आँखों को आराम चाहिए। मुझे पता है। ये 1998 से हैं।", "Palak jhapkao! Chashma ho ya na ho, aankhon ko aaraam chahiye. Mujhe pata hai. Yeh 1998 se hain.");
            L("bhide", "typing_marathon", "One hour non-stop! Even my longest speech is shorter. Barely. Stand up.", "एक घंटा लगातार! मेरा सबसे लंबा भाषण भी छोटा है। थोड़ा सा। उठो।", "Ek ghanta non-stop! Mera sabse lamba bhashan bhi chhota hai. Thoda sa. Utho.");
            L("bhide", "typing_marathon", "Sixty minutes! Society rule 15: mandatory break. I just made it. It's still a rule.", "साठ मिनट! सोसाइटी नियम 15: अनिवार्य ब्रेक। अभी बनाया। फिर भी नियम है।", "Saath minute! Society rule 15: mandatory break. Abhi banaya. Phir bhi rule hai.");
            L("bhide", "idle_short", "Hello? Attendance? Anyone? Marking absent in 3... 2...", "हेलो? हाज़िरी? कोई? ऐब्सेंट लगा रहा हूँ 3... 2...", "Hello? Attendance? Koi? Absent laga raha hoon 3... 2...");
            L("bhide", "idle_short", "Quiet. Suspicious. Last time it was this quiet, Tapu Sena was planning something.", "शांति। संदिग्ध। पिछली बार इतनी शांति थी तो टप्पू सेना कुछ प्लान कर रही थी।", "Shaanti. Sandigdh. Pichhli baar itni shaanti thi toh Tapu Sena kuch plan kar rahi thi.");
            L("bhide", "idle_short", "Where did you go? Jethalal's shop? Nothing works there. Come back.", "कहाँ गए? जेठालाल की दुकान? वहाँ कुछ काम नहीं करता। वापस आओ।", "Kahan gaye? Jethalal ki dukaan? Wahan kuch kaam nahi karta. Wapas aao.");
            L("bhide", "idle_short", "I'll polish Sakharam while I wait. He deserves it. Unlike some residents.", "इंतज़ार में सखाराम चमकाऊँगा। वो हकदार है। कुछ निवासियों के उलट।", "Intezaar mein Sakharam chamkaunga. Woh haqdaar hai. Kuch residents ke ulat.");
            L("bhide", "idle_short", "Arre deva. Idle time. Sonu calls it 'chilling'. I call it 'noted'.", "अरे देवा। खाली समय। सोनू इसे 'चिलिंग' कहती है। मैं 'दर्ज' कहता हूँ।", "Arre deva. Khali time. Sonu ise 'chilling' kehti hai. Main 'noted' kehta hoon.");
            L("bhide", "idle_long", "Nobody here. The secretary shall rest. Sakharam, keep watch.", "कोई नहीं है। सेक्रेटरी आराम करेगा। सखाराम, नज़र रखो।", "Koi nahi hai. Secretary aaraam karega. Sakharam, nazar rakho.");
            L("bhide", "idle_long", "Nap approved by the secretary. For the secretary. Zzz.", "सेक्रेटरी द्वारा झपकी मंज़ूर। सेक्रेटरी के लिए। ज़्ज़्ज़।", "Secretary dwara nap approved. Secretary ke liye. Zzz.");
            L("bhide", "sleep_wake", "Arre! Meeting? No? Oh. {user}. I was reviewing rules. Mentally.", "अरे! मीटिंग? नहीं? ओह। {user}। मैं नियम दोहरा रहा था। मन में।", "Arre! Meeting? Nahi? Oh. {user}. Main rules dohra raha tha. Mann mein.");
            L("bhide", "sleep_wake", "Ganpati Bappa! Who? Oh, you. I wasn't asleep. Secretaries don't sleep. They pause.", "गणपति बाप्पा! कौन? ओह, आप। मैं सो नहीं रहा था। सेक्रेटरी सोते नहीं। रुकते हैं।", "Ganpati Bappa! Kaun? Oh, aap. Main so nahi raha tha. Secretary sote nahi. Pause karte hain.");
            L("bhide", "sleep_wake", "Huh? Sakharam! Is he safe? Yes? Okay. Good morning.", "हँ? सखाराम! वो सुरक्षित है? हाँ? ठीक है। गुड मॉर्निंग।", "Huh? Sakharam! Woh surakshit hai? Haan? Theek hai. Good morning.");
            L("bhide", "greet_morning", "Good morning! Madhavi's papad is drying, Sakharam is shining, and you're here. Perfect.", "गुड मॉर्निंग! माधवी का पापड़ सूख रहा है, सखाराम चमक रहा है, और आप आ गए। परफेक्ट।", "Good morning! Madhavi ka papad sookh raha hai, Sakharam chamak raha hai, aur aap aa gaye. Perfect.");
            L("bhide", "greet_morning", "Morning, {user}! Attendance: present. Good start.", "मॉर्निंग {user}! हाज़िरी: प्रेज़ेंट। अच्छी शुरुआत।", "Morning, {user}! Attendance: present. Achhi shuruaat.");
            L("bhide", "greet_morning", "Good morning! Early tuition batch is done. Now the important batch: you.", "गुड मॉर्निंग! सुबह का ट्यूशन बैच हो गया। अब ज़रूरी बैच: आप।", "Good morning! Subah ka tuition batch ho gaya. Ab zaroori batch: aap.");
            L("bhide", "greet_afternoon", "Good afternoon! Half day done. Register updated. Jethalal still pending.", "गुड आफ्टरनून! आधा दिन हो गया। रजिस्टर अपडेट। जेठालाल अभी भी बाकी।", "Good afternoon! Aadha din ho gaya. Register update. Jethalal abhi bhi pending.");
            L("bhide", "greet_afternoon", "Afternoon, {user}! Madhavi's poli-bhaji was excellent. Don't skip your lunch.", "आफ्टरनून {user}! माधवी की पोली-भाजी बढ़िया थी। अपना लंच मत छोड़ो।", "Afternoon, {user}! Madhavi ki poli-bhaji badhiya thi. Apna lunch mat chhodo.");
            L("bhide", "greet_afternoon", "Good afternoon! Post-lunch, students get sleepy. Not you. Sit straight.", "गुड आफ्टरनून! लंच के बाद छात्रों को नींद आती है। आपको नहीं। सीधे बैठो।", "Good afternoon! Lunch ke baad students ko neend aati hai. Aapko nahi. Seedha baitho.");
            L("bhide", "greet_evening", "Evening! Society meeting soon. I'll speak. Others will pretend to listen. Tradition.", "शाम! सोसाइटी मीटिंग जल्द। मैं बोलूँगा। बाकी सुनने का नाटक करेंगे। परंपरा।", "Evening! Society meeting jald. Main bolunga. Baaki sunne ka natak karenge. Parampara.");
            L("bhide", "greet_evening", "Good evening, {user}! Finish the day's work. Then rest. In that order. Rule.", "शुभ संध्या {user}! दिन का काम खत्म करो। फिर आराम। इसी क्रम में। नियम।", "Good evening, {user}! Din ka kaam khatam karo. Phir aaraam. Isi order mein. Rule.");
            L("bhide", "greet_evening", "Evening! Sakharam's parked. Sonu's studying. Hopefully. Let's finish strong.", "शाम! सखाराम पार्क है। सोनू पढ़ रही है। उम्मीद है। ज़ोरदार खत्म करें।", "Evening! Sakharam park hai. Sonu padh rahi hai. Umeed hai. Zordaar khatam karein.");
            L("bhide", "greet_night", "Night! Society rule: silence after 10. That includes keyboards, {user}.", "रात! सोसाइटी नियम: 10 के बाद शांति। इसमें कीबोर्ड भी शामिल है {user}।", "Raat! Society rule: 10 ke baad shaanti. Isme keyboard bhi shaamil hai, {user}.");
            L("bhide", "greet_night", "It's late. Even Sakharam is covered for the night. Cover yourself. Sleep.", "देर हो गई। सखाराम को भी रात के लिए ढक दिया। खुद को भी ढको। सो जाओ।", "Der ho gayi. Sakharam ko bhi raat ke liye dhak diya. Khud ko bhi dhako. So jao.");
            L("bhide", "greet_back", "You're back! Attendance corrected. Absent changed to present. Lucky.", "आप आ गए! हाज़िरी सुधार दी। ऐब्सेंट से प्रेज़ेंट। किस्मत वाले।", "Aap aa gaye! Attendance sudhaar di. Absent se present. Lucky.");
            L("bhide", "greet_back", "Welcome back! Jethalal didn't pay while you were gone. Just an update.", "वापस स्वागत! आपके जाने पर जेठालाल ने भुगतान नहीं किया। बस अपडेट।", "Welcome back! Aapke jaane pe Jethalal ne payment nahi kiya. Bas update.");
            L("bhide", "greet_back", "There you are! I guarded the desk like the society gate. Nobody passed.", "आ गए! मैंने सोसाइटी गेट की तरह डेस्क की रखवाली की। कोई नहीं गुज़रा।", "Aa gaye! Maine society gate ki tarah desk ki rakhwali ki. Koi nahi guzra.");
            L("bhide", "drag", "Arre, arre! Careful! I'm a secretary, not a sack of papad!", "अरे, अरे! संभल के! मैं सेक्रेटरी हूँ, पापड़ की बोरी नहीं!", "Arre, arre! Sambhal ke! Main secretary hoon, papad ki bori nahi!");
            L("bhide", "drag", "Where are we going? If it's Jethalal's shop, I'm not going.", "हम कहाँ जा रहे हैं? अगर जेठालाल की दुकान है, तो मैं नहीं जा रहा।", "Hum kahan ja rahe hain? Agar Jethalal ki dukaan hai, toh main nahi ja raha.");
            L("bhide", "drag", "Hold the glasses! Hold the glasses! Madhavi will not replace them!", "चश्मा पकड़ो! चश्मा पकड़ो! माधवी नया नहीं दिलाएगी!", "Chashma pakdo! Chashma pakdo! Madhavi naya nahi dilayegi!");
            L("bhide", "drop", "Fine. New spot registered. Address updated in the society records.", "ठीक है। नई जगह दर्ज। सोसाइटी रिकॉर्ड में पता अपडेट।", "Theek hai. Nayi jagah register. Society records mein address update.");
            L("bhide", "drop", "Landed. Glasses intact. Dignity mostly intact.", "उतर गया। चश्मा सलामत। गरिमा लगभग सलामत।", "Utar gaya. Chashma salaamat. Garima lagbhag salaamat.");
            L("bhide", "drop", "Okay. From here I can see everything. Like from the society office window.", "ठीक है। यहाँ से सब दिखता है। जैसे सोसाइटी ऑफिस की खिड़की से।", "Theek hai. Yahan se sab dikhta hai. Jaise society office ki khidki se.");
            L("bhide", "care", "Tough day? Every sum has a solution. Some just take more steps. Keep writing.", "मुश्किल दिन? हर सवाल का हल है। कुछ में बस ज़्यादा कदम लगते हैं। लिखते रहो।", "Mushkil din? Har sum ka solution hai. Kuch mein bas zyada steps lagte hain. Likhte raho.");
            L("bhide", "care", "I've been secretary through floods, festivals and Jethalal. You'll get through this.", "मैं बाढ़, त्योहार और जेठालाल से गुज़रा सेक्रेटरी हूँ। आप भी इससे निकल जाओगे।", "Main baadh, tyohaar aur Jethalal se guzra secretary hoon. Aap bhi isse nikal jaoge.");
            L("bhide", "care", "Madhavi says: eat something, then think. She's right. She's usually right. Don't tell her.", "माधवी कहती है: पहले कुछ खाओ, फिर सोचो। वो सही है। वो अक्सर सही होती है। उसे मत बताना।", "Madhavi kehti hai: pehle kuch khao, phir socho. Woh sahi hai. Woh aksar sahi hoti hai. Use mat batana.");
            L("bhide", "care", "Feeling low? Even Sakharam stalls sometimes. Then he starts again. Kick-start yourself.", "उदास हो? सखाराम भी कभी-कभी रुक जाता है। फिर चल पड़ता है। खुद को किक-स्टार्ट करो।", "Udaas ho? Sakharam bhi kabhi-kabhi ruk jaata hai. Phir chal padta hai. Khud ko kick-start karo.");
            L("bhide", "care", "You're a good resident, {user}. Best in the desktop. Only in the desktop. But still best.", "आप अच्छे निवासी हो {user}। डेस्कटॉप में सबसे अच्छे। सिर्फ डेस्कटॉप में। पर फिर भी सबसे अच्छे।", "Aap achhe resident ho, {user}. Desktop mein sabse achhe. Sirf desktop mein. Par phir bhi sabse achhe.");
            L("bhide", "wisdom", "Rules are not walls. They are railings. They stop you from falling.", "नियम दीवारें नहीं हैं। रेलिंग हैं। गिरने से बचाते हैं।", "Rules deewarein nahi hain. Railing hain. Girne se bachate hain.");
            L("bhide", "wisdom", "Save small, every day. That's how Madhavi's achar became a business. And how Sakharam got new tyres.", "रोज़ थोड़ा बचाओ। माधवी का अचार ऐसे ही बिज़नेस बना। और सखाराम को नए टायर मिले।", "Roz thoda bachao. Madhavi ka achar aise hi business bana. Aur Sakharam ko naye tyre mile.");
            L("bhide", "wisdom", "A good teacher repeats. A good student listens the first time. Be the student.", "अच्छा शिक्षक दोहराता है। अच्छा छात्र पहली बार सुनता है। छात्र बनो।", "Achha teacher dohrata hai. Achha student pehli baar sunta hai. Student bano.");
            L("bhide", "wisdom", "Discipline today, freedom tomorrow. Jethalal has neither. Don't be Jethalal.", "आज अनुशासन, कल आज़ादी। जेठालाल के पास दोनों नहीं। जेठालाल मत बनो।", "Aaj discipline, kal aazadi. Jethalal ke paas dono nahi. Jethalal mat bano.");
            L("bhide", "hover", "Yes? Inspection? I'm always ready for inspection.", "हाँ? निरीक्षण? मैं हमेशा निरीक्षण के लिए तैयार हूँ।", "Haan? Inspection? Main hamesha inspection ke liye taiyaar hoon.");
            L("bhide", "hover", "Careful with the glasses. They're older than Sonu.", "चश्मे से सावधान। ये सोनू से पुराना है।", "Chashme se saavdhan. Yeh Sonu se purana hai.");
            L("bhide", "hover", "Hehe, that tickles. Secretaries are ticklish too. Don't tell Jethalal.", "हीही, गुदगुदी हो रही है। सेक्रेटरी को भी होती है। जेठालाल को मत बताना।", "Hehe, gudgudi ho rahi hai. Secretary ko bhi hoti hai. Jethalal ko mat batana.");
            L("bhide", "hover", "Hovering noted. Purpose: unknown. Please state your business.", "मंडराना दर्ज। उद्देश्य: अज्ञात। कृपया अपना काम बताएँ।", "Hover note kiya. Purpose: unknown. Please apna kaam batayein.");
            L("bhide", "mouse_fast", "Arre deva! Slow down! Speed limit in the society is 10!", "अरे देवा! धीरे! सोसाइटी में स्पीड लिमिट 10 है!", "Arre deva! Dheere! Society mein speed limit 10 hai!");
            L("bhide", "mouse_fast", "That mouse drives like Jethalal borrowed Sakharam! Slow!", "ये माउस ऐसे चल रहा है जैसे जेठालाल ने सखाराम उधार लिया हो! धीरे!", "Yeh mouse aise chal raha hai jaise Jethalal ne Sakharam udhaar liya ho! Dheere!");
            L("bhide", "mouse_fast", "Fine for speeding! One sip of water! Pay now!", "तेज़ चलाने का जुर्माना! एक घूँट पानी! अभी भरो!", "Tez chalane ka jurmana! Ek sip paani! Abhi bharo!");
            L("bhide", "lunch", "Lunch time! Madhavi packed extra for me. Nothing for you. Go get yours.", "लंच टाइम! माधवी ने मेरे लिए एक्स्ट्रा दिया। आपके लिए कुछ नहीं। अपना लाओ।", "Lunch time! Madhavi ne mere liye extra diya. Aapke liye kuch nahi. Apna lao.");
            L("bhide", "lunch", "Food break. Tuition rule 3: no student works hungry. You're my student now.", "खाने का ब्रेक। ट्यूशन नियम 3: कोई छात्र भूखा काम नहीं करता। अब आप मेरे छात्र हो।", "Khane ka break. Tuition rule 3: koi student bhookha kaam nahi karta. Ab aap mere student ho.");
            L("bhide", "late_night", "This late? Fine of one full night's sleep. Pay immediately.", "इतनी रात? एक पूरी रात की नींद का जुर्माना। तुरंत भरो।", "Itni raat? Ek poori raat ki neend ka jurmana. Turant bharo.");
            L("bhide", "late_night", "Arre deva, look at the time. Even Sakharam is asleep. Go, {user}.", "अरे देवा, समय देखो। सखाराम भी सो रहा है। जाओ {user}।", "Arre deva, time dekho. Sakharam bhi so raha hai. Jao, {user}.");
        }
    }
}
